package com.vajjha.recipes.model;import com.fasterxml.jackson.databind.JsonNode;import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.Instant;@Entity @Table(name="recipes") public class Recipe{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String title;@Column(nullable=false,unique=true)private String slug;@Column(columnDefinition="text")private String description;@Column(name="image_url")private String imageUrl;@Column(name="prep_minutes")private Integer prepMinutes;@Column(name="cook_minutes")private Integer cookMinutes;private Integer servings;private String difficulty;private String cuisine;@JdbcTypeCode(SqlTypes.JSON)@Column(columnDefinition="jsonb")private JsonNode ingredients;@JdbcTypeCode(SqlTypes.JSON)@Column(columnDefinition="jsonb")private JsonNode instructions;@JdbcTypeCode(SqlTypes.JSON)@Column(columnDefinition="jsonb")private JsonNode tags;@Column(name="is_favorite")private boolean isFavorite;@Column(name="is_published")private boolean isPublished;@Column(name="category_id")private Long categoryId;@Column(name="created_at")private Instant createdAt;@Column(name="updated_at")private Instant updatedAt;@PrePersist void create(){createdAt=Instant.now();updatedAt=createdAt;if(ingredients==null)ingredients=com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.arrayNode();if(instructions==null)instructions=com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.arrayNode();if(tags==null)tags=com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.arrayNode();}@PreUpdate void update(){updatedAt=Instant.now();}public Long getId(){return id;}public String getTitle(){return title;}public String getSlug(){return slug;}public String getDescription(){return description;}public String getImageUrl(){return imageUrl;}public Integer getPrepMinutes(){return prepMinutes;}public Integer getCookMinutes(){return cookMinutes;}public Integer getServings(){return servings;}public String getDifficulty(){return difficulty;}public String getCuisine(){return cuisine;}public JsonNode getIngredients(){return ingredients;}public JsonNode getInstructions(){return instructions;}public JsonNode getTags(){return tags;}public boolean isFavorite(){return isFavorite;}public Long getCategoryId(){return categoryId;}public Instant getCreatedAt(){return createdAt;}public void setTitle(String v){title=v;}public void setSlug(String v){slug=v;}public void setDescription(String v){description=v;}public void setImageUrl(String v){imageUrl=v;}public void setPrepMinutes(Integer v){prepMinutes=v;}public void setCookMinutes(Integer v){cookMinutes=v;}public void setServings(Integer v){servings=v;}public void setDifficulty(String v){difficulty=v;}public void setCuisine(String v){cuisine=v;}public void setIngredients(JsonNode v){ingredients=v;}public void setInstructions(JsonNode v){instructions=v;}public void setTags(JsonNode v){tags=v;}public void setFavorite(boolean v){isFavorite=v;}public void setPublished(boolean v){isPublished=v;}public void setCategoryId(Long v){categoryId=v;}}